"""R4.3.1 / R4.3.1a: a program's `## Roll-up`, regenerated by the write that
invalidates it.

Roll-ups are the one piece of derived data that lives IN the source of truth
rather than beside it, so C3's "everything derived is disposable" does not
protect them: a stale roll-up is a wrong answer sitting in a committed file,
and the user reads it. If only an explicit `brain build` fixed one, every
brain would carry stale roll-ups between builds with nothing to say so - the
same silent-staleness failure R4.8.2 argues against, in the one place it
actually matters.

Regeneration therefore happens inside the same lock, checkpoint and commit as
the write that caused it (R6.5, R11.7), and must be the LAST thing inside that
envelope: the tree is shared for the length of one command (R4.8.2), and
nothing resolves against it afterwards.
"""
from __future__ import annotations

from pathlib import Path
from typing import List, Tuple

SECTION = "Roll-up"

# Only these fields. A roll-up is a summary a human scans, and every column
# here is one `brain check` can recompute from the projects themselves - which
# is what makes it safe to overwrite wholesale (R4.3.1's machine-owned rule)
# rather than needing the surgical line-level edits R5.1 demands of user text.
_HEADER = ("| Project | Status | Health | Open | Next |",
           "|---|---|---|---|---|")


def _cell(text) -> str:
    """A table cell that cannot break the table.

    The project's `## Next actions` text is the user's words (R4.6.1), and a
    `|` in it would forge a column - the same collision the digest hardens
    against on its own way out. Newlines cannot occur (a command is one line,
    R6.4) but a hand-edited file can hold one, so they go too.
    """
    flat = " ".join(str(text or "").replace("|", "/").split())
    return flat if len(flat) <= 48 else flat[:47].rstrip() + "…"


def table(tree, program_slug: str) -> str:
    """The `## Roll-up` body for one program: its projects, one row each.

    Projects declare their program (R4.1's "membership is declared on the
    child"), so this reads them rather than any list the program holds - a
    program that listed its own projects could disagree with them.
    """
    rows = list(_HEADER)
    projects = [p for p in tree.entities(kinds=("project",))
                if p.program == program_slug]
    for p in sorted(projects, key=lambda p: p.slug):
        open_actions = p.open_actions()
        nxt = _cell(open_actions[0].text) if open_actions else ""
        rows.append("| {} | {} | {} | {} | {} |".format(
            _cell(p.slug), _cell(p.status), _cell(p.health),
            len(open_actions), nxt))
    if not projects:
        rows.append("| _(no projects declare this program)_ |  |  |  |  |")
    return "\n".join(rows)


def programs_touched(tree, root, paths) -> List[str]:
    """Which programs a set of written paths invalidates.

    A project's row appears in exactly one program's roll-up, so writing a
    project touches its program - and writing a program touches itself only if
    something else changed its roll-up inputs, which nothing does.
    """
    slugs = set()
    for rel in paths:
        if not rel.startswith("projects/"):
            continue
        slug = Path(rel).stem
        for p in tree.entities(kinds=("project",)):
            if p.slug == slug and p.program:
                slugs.add(p.program)
    return sorted(slugs)


def refresh(tree, root, paths) -> Tuple[str, ...]:
    """Rewrite the roll-up of every program the given writes invalidated.

    Returns the program paths actually changed, for the caller to add to the
    same commit (R4.3.1a). A program whose roll-up already matches is left
    alone, so an unrelated write never widens a commit for nothing (R11.2).
    """
    written = []
    # The destination program, from the project's `program:` as it is NOW -
    # plus any program a project was moved OUT of during this command, which
    # only the tree saw (H1: `link` left the old roll-up still listing it).
    slugs = set(programs_touched(tree, root, paths))
    slugs |= getattr(tree, "stale_programs", set())
    for slug in sorted(slugs):
        rel = _rewrite(tree, root, slug)
        if rel is not None:
            written.append(rel)
    return tuple(written)


def _rewrite(tree, root, slug):
    """Rewrite one program's roll-up, or return None if nothing changed.

    Returning None for an unchanged roll-up is what keeps an unrelated write
    from widening its own commit (R11.2) and makes `brain build` a no-op on a
    brain that is already correct.
    """
    matches = [p for p in tree.entities(kinds=("program",)) if p.slug == slug]
    if not matches:
        return None                       # `program:` names something absent
    program = matches[0]
    doc = program.doc
    if doc.section(SECTION) is None:
        return None                       # tolerant loading (R4.2.4)
    before = list(doc.lines)
    doc.set_section(SECTION, table(tree, slug))
    if doc.lines == before:
        return None
    doc.save()
    return Path(program.path).relative_to(Path(root)).as_posix()


def refresh_all(tree, root, program_slugs) -> Tuple[str, ...]:
    """Rewrite the roll-up of every named program (`brain build`).

    Shares `_rewrite` with `refresh`, so the table `build` produces and the
    one an ordinary write produces cannot drift - which matters because
    `brain check` will compare a committed roll-up against a regenerated one
    to decide whether it was hand-edited (R4.3.1).
    """
    written = []
    for slug in program_slugs:
        rel = _rewrite(tree, root, slug)
        if rel is not None:
            written.append(rel)
    return tuple(written)
